use core::iter::FusedIterator;

use super::{FragmentKey, tree::FragmentTree};
use crate::input::LayoutInputKey;

/// Fragments generated by one source item in layout order, following
/// [`FragmentLink::next`](super::FragmentLink::next).
///
/// Created by [`FragmentTree::fragments`].
pub struct Fragments<'a> {
    tree: &'a FragmentTree,
    source: LayoutInputKey,
    next: Option<FragmentKey>,
}

impl<'a> Fragments<'a> {
    pub(super) fn new(tree: &'a FragmentTree, source: LayoutInputKey) -> Self {
        let next = tree.first.get(source).copied();

        Self { tree, source, next }
    }
}

impl Iterator for Fragments<'_> {
    type Item = FragmentKey;

    fn next(&mut self) -> Option<FragmentKey> {
        // Stale keys end the chain; deleted fragment keys are never reused.
        let key = self.next.take().filter(|&key| {
            self.tree
                .items
                .get(key)
                .is_some_and(|fragment| fragment.source == self.source)
        })?;

        self.next = self.tree.items[key].link.next;

        Some(key)
    }
}

impl FusedIterator for Fragments<'_> {}
